// Samakan kunci dengan config/app.php > ingest_key.
const API_KEY = "halocake-dev-2026-GANTI-DENGAN-KUNCI-RAHASIA";
// Node-RED dan Laragon di PC yang sama; jika beda PC, ganti dengan IP PC Laragon.
const API_URL = "http://127.0.0.1/halocake/api/ingest.php";
let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); }
    catch (err) { node.warn("Pesan MQTT bukan JSON: " + err.message); return null; }
}
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    node.warn("MQTT harus berupa objek JSON.");
    return null;
}
msg.url = API_URL;
msg.method = "POST";
msg.headers = { "Content-Type": "application/json", "X-API-Key": API_KEY };
msg.payload = payload;
return msg;
